package com.cove.chat.data.udpmedia

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import java.util.Base64

/** Exact-bytes vectors generated by the Go reference (`backend/tests/udpmedia_vectors_test.go`). */
class KeyringVectorsTest {
    private val c2sKey = "bf32d49e944023c19e748a0eb82776d79ceff18408d1a4de307475836186c108"
    private val s2cKey = "3d2847a52f982509982d9093cab7ade816c55ad8a7d19bedbb2dd56407962170"
    private val c2sSalt = "7d8ec2ae"
    private val s2cSalt = "16a7f268"
    private val clientSeq0Media = "c1030000a0a1a2a3a4a5a6a700000000000000003c003883f5c22a4c93f1a6e7c18184b4254907ce7834cd4d67f01bdb08df8cdd62eeb67ed127ffb34dc0046fe2a574ad1c42e34a9958f57f"
    private val clientSeq1Hello = "c1010000a0a1a2a3a4a5a6a70000000000000001e6c7dbbdce3adc7ef0eafe7f0007f5e7"
    private val serverSeq0Ack = "c1020000a0a1a2a3a4a5a6a70000000000000000384f54bb6b63df3e7a4a37d2f502a396c6bedd84e1b58d327a22776dd240dfd9d2d50182636e7d45590ab6f6d83f66597cde6224b11b23a0"
    private val clientEpoch1Seq0 = "c1030100a0a1a2a3a4a5a6a7000000000000000068912a01b7a1542c2ee53a745b04c6127e9280303cc0b4a6675efa822c2fca911a6da8d2a229493562e9a512fe428512d4dcd0745e633ee0"

    private fun reason(block: () -> Unit): UdpMediaException.Reason =
        assertThrows(UdpMediaException::class.java) { block() }.reason

    @Test fun hkdfLabelsProduceTheGoKeys() {
        val prk = Hkdf.extract(Vec.sid + Vec.clientNonce + Vec.serverNonce, Vec.shared)
        val ctx = "|${Vec.CHANNEL}|${Vec.USER}"
        fun ex(l: String, n: Int) = Hkdf.expand(prk, (l + ctx).toByteArray(), n).toHex()
        assertEquals(c2sKey, ex("cove-udpmedia/v1/c2s/key", 32))
        assertEquals(s2cKey, ex("cove-udpmedia/v1/s2c/key", 32))
        assertEquals(c2sSalt, ex("cove-udpmedia/v1/c2s/salt", 4))
        assertEquals(s2cSalt, ex("cove-udpmedia/v1/s2c/salt", 4))
    }

    @Test fun clientPacketsMatchGoBytes() {
        val cli = Vec.ring(Role.CLIENT)
        assertEquals(clientSeq0Media, cli.seal(PacketType.MEDIA, Vec.plain).toHex())
        assertEquals(clientSeq1Hello, cli.seal(PacketType.HELLO, ByteArray(0)).toHex())
    }

    @Test fun serverPacketMatchesGoBytes() {
        assertEquals(serverSeq0Ack, Vec.ring(Role.SERVER).seal(PacketType.HELLO_ACK, Vec.plain).toHex())
    }

    @Test fun epochOneMatchesGoBytesAndServerFollowsTheRatchet() {
        val cli = Vec.ring(Role.CLIENT)
        cli.rotate()
        assertEquals(1, cli.epoch())
        assertEquals(clientEpoch1Seq0, cli.seal(PacketType.MEDIA, Vec.plain).toHex())
        val srv = Vec.ring(Role.SERVER)
        val (h, pt) = srv.open(hex(clientEpoch1Seq0))
        assertEquals(1, h.epoch)
        assertArrayEquals(Vec.plain, pt)
        assertEquals(1, srv.epoch())
    }

    @Test fun openDecryptsGoPacketsBothDirections() {
        val srv = Vec.ring(Role.SERVER)
        val (h, pt) = srv.open(hex(clientSeq0Media))
        assertEquals(PacketType.MEDIA, h.type)
        assertEquals(0L, h.seq)
        assertArrayEquals(Vec.plain, pt)
        assertArrayEquals(Vec.plain, Vec.ring(Role.CLIENT).open(hex(serverSeq0Ack)).second)
    }

    @Test fun tamperingAnyByteFailsAuthentication() {
        val good = hex(clientSeq0Media)
        // Header bytes 0..11 select magic/session/epoch and fail earlier; everything from the sequence on is AEAD-covered.
        for (i in 12 until good.size) {
            val bad = good.copyOf()
            bad[i] = (bad[i].toInt() xor 1).toByte()
            assertEquals("byte $i", UdpMediaException.Reason.AUTH, reason { Vec.ring(Role.SERVER).open(bad) })
        }
        val flippedType = good.copyOf().also { it[1] = 9 }
        assertEquals(UdpMediaException.Reason.AUTH, reason { Vec.ring(Role.SERVER).open(flippedType) })
    }

    @Test fun reflectedPacketDoesNotVerifyForItsSender() {
        assertEquals(UdpMediaException.Reason.AUTH, reason { Vec.ring(Role.CLIENT).open(hex(clientSeq0Media)) })
    }

    @Test fun replayIsRejectedAndForgedPacketsDoNotMoveTheWindow() {
        val srv = Vec.ring(Role.SERVER)
        val cli = Vec.ring(Role.CLIENT)
        val p0 = cli.seal(PacketType.MEDIA, Vec.plain)
        srv.open(p0)
        assertEquals(UdpMediaException.Reason.REPLAY, reason { srv.open(p0) })
        val forged = p0.copyOf().also { it[12] = 0x7F; it[19] = 0 }
        assertEquals(UdpMediaException.Reason.AUTH, reason { srv.open(forged) })
        srv.open(cli.seal(PacketType.MEDIA, Vec.plain)) // honest traffic still flows
    }

    @Test fun reorderWithinTheWindowIsAcceptedOldIsNot() {
        val srv = Vec.ring(Role.SERVER)
        val cli = Vec.ring(Role.CLIENT)
        val pkts = List(1100) { cli.seal(PacketType.MEDIA, byteArrayOf(it.toByte())) }
        srv.open(pkts[1099])
        srv.open(pkts[1090])
        assertEquals(UdpMediaException.Reason.REPLAY, reason { srv.open(pkts[10]) })
    }

    @Test fun malformedPacketsAreRejectedWithTheRightReason() {
        val good = hex(clientSeq0Media)
        val srv = Vec.ring(Role.SERVER)
        assertEquals(UdpMediaException.Reason.WRONG_SESSION, reason { srv.open(good.copyOf().also { it[5] = 0 }) })
        assertEquals(UdpMediaException.Reason.BAD_MAGIC, reason { srv.open(good.copyOf().also { it[0] = 1 }) })
        assertEquals(UdpMediaException.Reason.SHORT_PACKET, reason { srv.open(good.copyOf(30)) })
        assertEquals(UdpMediaException.Reason.TOO_LARGE, reason { srv.open(ByteArray(1201)) })
        assertEquals(UdpMediaException.Reason.BAD_EPOCH, reason { srv.open(good.copyOf().also { it[2] = 5 }) })
    }

    @Test fun sealRefusesOversizedPlaintext() {
        assertEquals(UdpMediaException.Reason.TOO_LARGE, reason { Vec.ring(Role.CLIENT).seal(PacketType.MEDIA, ByteArray(Wire.MAX_PLAINTEXT + 1)) })
        Vec.ring(Role.CLIENT).seal(PacketType.MEDIA, ByteArray(Wire.MAX_PLAINTEXT)) // the exact limit fits
    }

    @Test fun sealRotatesAfterTenMinutesAndPreviousEpochHasAGracePeriod() {
        var t = 0L
        val cli = Vec.ring(Role.CLIENT) { t }
        val srv = Vec.ring(Role.SERVER) { t }
        val old = cli.seal(PacketType.MEDIA, byteArrayOf(1))
        val oldAgain = cli.seal(PacketType.MEDIA, byteArrayOf(4))
        t = Keyring.ROTATE_INTERVAL_MS
        val fresh = cli.seal(PacketType.MEDIA, byteArrayOf(2))
        assertEquals(1, cli.epoch())
        assertEquals(1, PacketHeader.parse(fresh).epoch)
        srv.open(fresh)
        assertEquals(1, srv.epoch())
        srv.open(old) // reordered epoch-0 packet, inside the grace period
        t += Keyring.PREV_EPOCH_GRACE_MS + 1
        assertEquals(UdpMediaException.Reason.BAD_EPOCH, reason { srv.open(oldAgain) })
    }

    @Test fun forgedNextEpochPacketNeverRatchets() {
        val srv = Vec.ring(Role.SERVER)
        val bogus = hex(clientEpoch1Seq0).also { it[40] = (it[40].toInt() xor 1).toByte() }
        assertEquals(UdpMediaException.Reason.AUTH, reason { srv.open(bogus) })
        assertEquals(0, srv.epoch())
        srv.open(hex(clientEpoch1Seq0)) // the genuine one still works afterwards
        assertEquals(1, srv.epoch())
    }

    @Test fun clientJoinHandshakeAgreesWithAServerKeyring() {
        val join = ClientJoin.create()
        val dec = Base64.getDecoder()
        val enc = Base64.getEncoder()
        // Server side, as Go AcceptJoin does it.
        val spriv = X25519.generatePrivate()
        val shared = X25519.sharedSecret(spriv, dec.decode(join.clientPub))
        val sid = ByteArray(8) { (it + 1).toByte() }
        val sn = ByteArray(16) { (it + 40).toByte() }
        val srv = Keyring(Role.SERVER, sid, shared, dec.decode(join.clientNonce), sn, "c", "u")
        val resp = JoinResponse(enc.encodeToString(sid), enc.encodeToString(X25519.publicKey(spriv)), enc.encodeToString(sn), 3, 1200, 0)
        val cli = join.complete(resp, "c", "u")
        assertArrayEquals(Vec.plain, srv.open(cli.seal(PacketType.MEDIA, Vec.plain)).second)
        assertArrayEquals(Vec.plain, cli.open(srv.seal(PacketType.MEDIA, Vec.plain)).second)
    }

    @Test fun malformedJoinResponseIsRejected() {
        val join = ClientJoin.create()
        val enc = Base64.getEncoder()
        assertThrows(UdpMediaException::class.java) { join.complete(JoinResponse("!!", "x", "y", 1, 1200, 0), "c", "u") }
        val shortSid = JoinResponse(enc.encodeToString(ByteArray(7)), enc.encodeToString(ByteArray(32)), enc.encodeToString(ByteArray(16)), 1, 1200, 0)
        assertThrows(UdpMediaException::class.java) { join.complete(shortSid, "c", "u") }
    }
}
